import { canonical, decodeToken, verifySignature } from "./verify";

// Generated by the backend (app.modules.passport.credential.qr_token) with the dev key.
const TOKEN = "eNpNjs1Og0AUhV_F3DVjCkx_IOmG_khIMQEbE7ubAjNOKASRVrDpI7j0DcbElXHlsr7KPIqX6MKzmJxz8uXOOUIF7hEO4JoGyBRcMP9ELBSxUYSiyPCfwIASUa2-tPrUby9afWh1vtDqVavvvlJnrd7xRTBBMJc1KxmGLQavLzkaX4p79I8Nei5LtsNw2GOwBtaYDHBB_1H9W4wucVJt9jweaep9ZuDZfnDeVISnJktTi7KJbcEJGeyzxYgWO1tklEdOsH5Y3RSzed0uuokYyzaZh9eV42-Y8K_iwNyyNd2ERXcbiW65evJoYgdimD7H8TITYdB6zl3ul3wWTadw-gGl4GM8";
const KEY = "DANnJudx+WRxr39RW9QGwJhn8FCnhBhv8AYvooO7UQQ=";

test("canonical JSON matches the backend", () => {
  expect(canonical({ b: 1, a: [true, "x"], c: { z: null, y: "शर्मा" } })).toBe('{"a":[true,"x"],"b":1,"c":{"y":"शर्मा","z":null}}');
});

test("a genuine QR verifies offline; a changed band does not", async () => {
  const decoded = await decodeToken(TOKEN);
  expect(decoded?.payload.n).toBe("शर्मा किराना");
  expect(verifySignature(decoded!.payload, decoded!.signature, KEY)).toBe(true);
  expect(verifySignature({ ...decoded!.payload, b: "A" }, decoded!.signature, KEY)).toBe(false);
  expect(await decodeToken("not-a-token")).toBeNull();
});
